extern s16 add_calc_short_angle3(s16* pValue, s16 target, f32 fraction, s16 maxStep, s16 minStep) {
    f32 stepSize;
    s32 uTarget;
    s32 newValue;
    s32 uValue;

    if (target != *pValue) {
        uValue = (u16)*pValue;
        uTarget = (u16)target;

        if (uValue > uTarget) {
            uTarget += 65536; /* Add 360 short degrees */
        }

        stepSize = (uTarget - uValue) * fraction;

        if (stepSize > maxStep) {
            stepSize = maxStep;
        } else if (stepSize < minStep) {
            stepSize = minStep;
        }

        newValue = uValue + (s32)stepSize;
        if (newValue > uTarget) {
            newValue = uTarget;
        }
        *pValue = newValue;
    }

    return target - *pValue;
}

static int aQMgr_decide_idx_prob_table(u8* prob_table, int count) {
    static u8 decide_table[100];
    int idx0;
    int idx1;
    u8 prob;
    int res = 0;
    int idx;
    int i;
    u8 j;
    int k;

    bzero(decide_table, 100);
    j = 0;
    for (i = 0; i < count; i++) {
        for (prob = prob_table[i]; prob != 0; j++, prob--) {
            if (j >= 100) {
                break;
            }

            decide_table[j] = i;
        }
    }

    k = 30;
    while (k-- != 0) {
        idx0 = RANDOM(100);
        idx1 = RANDOM(100);
        j = decide_table[idx0];
        decide_table[idx0] = decide_table[idx1];
        decide_table[idx1] = j;
    }

    idx = RANDOM(100);
    if (idx >= 0 && idx < 100) {
        res = decide_table[idx];
    }

    return res;
}

static int mGcgba_IsTypes(Joy_wrk_c* joywork, u32 load_type, u32 program_type) {
  int gba_status = GBA2_GBA_STATE_TRANSMITTING;
  u8 status;
  u32 send;

  if (GBAGetStatus(Port, &status) != GBA_READY) {
    gba_status = GBA2_GBA_STATE_ERROR;
  }
  else {
    if (status & GBA_JSTAT_SEND) {
        u32 recv;
        u8 readStatus;

        if (GBARead(Port, (u8*)&recv, &readStatus) != GBA_READY) {
          gba_status = GBA2_GBA_STATE_ERROR;
          goto exit;
        }
        else {
            if (joywork->scan_state == 1) {
              if (load_type == mJOYSIO_ConvData((u8*)&recv)) {
                gba_status = GBA2_GBA_STATE_SUCCESS;
                goto exit;
              }

              if (program_type == mJOYSIO_ConvData((u8*)&recv)) {
                gba_status = GBA2_GBA_STATE_ALREADY_EXIST;
                goto exit;
              }

              gba_status = GBA2_GBA_STATE_ERROR;
              goto exit;
            }

            joywork->cmd_attempts = 0;
        }
      }

    send = 0xFFFE0105;
    send = mJOYSIO_ConvData((u8*)&send);

    if (GBAWrite(Port, (u8*)&send, &status) == GBA_READY) {
      joywork->scan_state = 1;
    }
    else {
      gba_status = GBA2_GBA_STATE_ERROR;
    }
  }

  exit:
  return gba_status;
}

static xyz_t eNight15Moon_GetNowMoonPos(xyz_t center_pos) {
    f32 right_x = center_pos.x + 100.0f;
    lbRTC_time_c rtc_time = Common_Get(time.rtc_time);
    xyz_t pos;

    if (rtc_time.hour >= 18 && rtc_time.hour < 21) {
        f32 sec = (rtc_time.min * 60.0f + rtc_time.sec) * (1.0f / 54.0f);

        pos.x = right_x - (rtc_time.hour - 18) * 66.666666f;
        pos.x -= sec;
    } else if (rtc_time.hour < 18) {
        pos.x = right_x;
    } else {
        pos.x = center_pos.x - 100.0f;
    }

    pos.z = center_pos.z;
    pos.y = center_pos.y;
    return pos;
}

