static void mEnv_ChangeRGBLight(u8* dst, u8* src_nxt_w0, u8* src_nxt_w1, u8* src_now_w0, u8* src_now_w1, f32 f0,
                                f32 f1) {
    f32 weather_change_bias = l_mEnv_electric_light.change_weather_env_rate;
    f32 inverse_weather_change_bias = 1.0f - weather_change_bias;
    int i;

    for (i = 0; i < 3; i++) {
        *dst =
            weather_change_bias * (f1 * (*src_nxt_w0 + f0 * ((f32)*src_nxt_w1 - (f32)*src_nxt_w0))) +
            inverse_weather_change_bias * (f1 * (*src_now_w0 + f0 * ((f32)*src_now_w1 - (f32)*src_now_w0)));

        dst++;
        src_nxt_w0++;
        src_nxt_w1++;
        src_now_w0++;
        src_now_w1++;
    }
}

static OSTime lbRTC_RTCTimeToTicks(const lbRTC_time_c* time)  {
  OSCalendarTime ctime;
  int i;
  int month = time->month;

  // Copy the lbRTC_time_c structure fields to OSCalendarTime fields
  ctime.sec = time->sec;
  ctime.min = time->min;
  ctime.hour = time->hour;
  ctime.mday = time->day;
  ctime.mon = month - 1;
  ctime.year = time->year;
  ctime.wday = month;
  ctime.yday = 0;

  // Get calendar year-day to start of current month
  for (i = 1; i < month; i++) {
    ctime.yday += lbRTC_GetDaysByMonth(time->year, (lbRTC_month_t)i);
  }

  ctime.yday += time->day;
  ctime.yday -= 1;
  ctime.msec = 0;
  ctime.usec = 0;

  // Convert the OSCalendarTime structure to ticks and return it
  return OSCalendarTimeToTicks(&ctime);
}

